private static void formatLongBinary(long value, byte[] buf, int offset, int length, boolean negative) {
    int bits = (length - 1) * 8;
    long max = 1l << bits;
    long val = Math.abs(value);

    if (val < 0 || val >= max) {
        throw new IllegalArgumentException("Value " + value + " is too large for " + length + " byte field.");
